import openpyxl, os
out=os.environ['OUT_XLSX']
wb=openpyxl.load_workbook(out)
ws=wb['Sheet1']
# Verify a few row calculations manually
mult={'D':70,'E':69,'F':64,'G':61,'H':58,'I':57,'J':52,'K':46,'L':45,'M':34,'N':22,'O':10,'P':4}
for r in [5, 15, 16, 34, 38]:
    if r < 38:
        val = sum((ws[f'{c}{r}'].value or 0) * m for c, m in mult.items())
        print(f'Row {r}: computed={val}, stored={ws[f"Q{r}"].value}, match={abs(val - ws[f"Q{r}"].value) < 1e-6}')
    else:
        total = sum(ws[f'Q{r2}'].value or 0 for r2 in range(3, 38))
        print(f'Row 38: computed_total={total}, stored={ws["Q38"].value}, match={abs(total - ws["Q38"].value) < 1e-6}')
# Check bold status
for r in [3, 5, 15, 38]:
    print(f'Q{r} bold: {ws[f"Q{r}"].font.bold}')
